mapper.select:
SELECT r.room_no, r.user_no, r.admin_no, user_member.nickname AS user_nickname, admin_member.nickname AS admin_nickname, r.status, r.category, CASE r.category WHEN 'MAIL' THEN '메일 문의' WHEN 'MAP' THEN '지도 문의' WHEN 'STOCK' THEN '증권 문의' WHEN 'NEWS' THEN '뉴스 문의' WHEN 'WEATHER' THEN '날씨 문의' WHEN 'CALENDAR' THEN '캘린더 문의' WHEN 'ETC' THEN '기타 문의' ELSE '일반 문의' END AS category_name, r.last_message, r.last_message_date, r.created_date, ( SELECT COUNT(*) FROM chat_message m WHERE m.room_no = r.room_no AND m.sender_no = r.user_no AND m.read_yn = 'N' ) AS unread_count FROM chat_room r LEFT JOIN member user_member ON r.user_no = user_member.no LEFT JOIN member admin_member ON r.admin_no = admin_member.no
AND r.status = #{status}
AND r.category = #{category}
AND ( TO_CHAR(r.room_no) LIKE '%' || #{keyword} || '%' OR LOWER(user_member.nickname) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(admin_member.nickname) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(r.last_message) LIKE '%' || LOWER(#{keyword}) || '%' )
ORDER BY CASE r.status WHEN 'OPEN' THEN 1 WHEN 'CLOSED' THEN 2 ELSE 3 END, r.last_message_date DESC NULLS LAST, r.created_date DESC OFFSET #{offset, jdbcType=NUMERIC} ROWS FETCH NEXT #{size, jdbcType=NUMERIC} ROWS ONLY

SELECT COUNT(*) FROM chat_room r LEFT JOIN member user_member ON r.user_no = user_member.no LEFT JOIN member admin_member ON r.admin_no = admin_member.no
AND r.status = #{status}
AND r.category = #{category}
AND ( TO_CHAR(r.room_no) LIKE '%' || #{keyword} || '%' OR LOWER(user_member.nickname) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(admin_member.nickname) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(r.last_message) LIKE '%' || LOWER(#{keyword}) || '%' )
